1	import { describe, expect, it } from "vitest";
2	import { applyAction, programFor } from "./index";
3	import type { GameEvent, GameState } from "./index";
4	import {
5	  DISCARD_ENERGY_DECK,
6	  attachBenchFromDeck,
7	  attachFromDeck,
8	  benchFromDeck,
9	  deepFreeze,
10	  driveSetup,
11	  expectErr,
12	  handFromDeck,
13	  handUid,
14	  mustApply,
15	  types,
16	} from "./testFixtures";
17	
18	// M5 op-slice: discardEnergy (§15 energy removal — the "hammer" family). One op
19	// takes Energy off the OPPONENT's board; `from` names both the eligible Pokémon
20	// and how many are hit, and all three arms land with a real printed card:
21	//   • opponentActive  — Mawile (sv03-143) "Special Eater", an onPlayToBench trigger;
22	//   • opponentChosen  — Crushing Hammer (sv01-168), behind a coin flip;
23	//   • opponentEach    — Giacomo (sv02-182), the sweep across their whole board.
24	// MANDATORY and exactly one Energy per affected Pokémon, so the only decision is
25	// WHICH: nothing matching is a no-op, a forced pick auto-resolves, and the park
26	// has NO decline. The fixture fix-hammer is the opponentChosen arm without the
27	// coin gate, so the park / forced pick / whiff gate are pinned without a seeded flip.
28	
29	function find<T extends GameEvent["type"]>(
30	  events: GameEvent[],
31	  type: T,
32	): Extract<GameEvent, { type: T }> | undefined {
33	  return events.find((e) => e.type === type) as Extract<GameEvent, { type: T }> | undefined;
34	}
35	
36	function findAll<T extends GameEvent["type"]>(
37	  events: GameEvent[],
38	  type: T,
39	): Extract<GameEvent, { type: T }>[] {
40	  return events.filter((e) => e.type === type) as Extract<GameEvent, { type: T }>[];
41	}
42	
43	/** Setup then open P1's turn 2 (P2 went first and passed) — P1's first
44	    unrestricted turn, so a Supporter (Giacomo) is legal. */
45	function board(seed: number): GameState {
46	  const state = driveSetup(
47	    seed,
48	    { p1: DISCARD_ENERGY_DECK, p2: DISCARD_ENERGY_DECK },
49	    { first: "p2" },
50	  );
51	  return mustApply(state, { type: "endTurn", seat: "p2" }).state;
52	}
53	
54	function activeEnergy(state: GameState, seat: "p1" | "p2"): string[] {
55	  return [...(state.players[seat].active?.energy ?? [])];
56	}
57	function benchEnergy(state: GameState, seat: "p1" | "p2", index: number): string[] {
58	  return [...(state.players[seat].bench[index]?.energy ?? [])];
59	}
60	
61	/** Play `cardId` from P1's hand (pulled out of their deck first) and return the
62	    result — the shared opening of almost every case below. */
63	function playFromHand(state: GameState, cardId: string) {
64	  const withCard = handFromDeck(state, "p1", cardId, 1);
65	  const uid = handUid(withCard, "p1", cardId);
66	  return mustApply(withCard, { type: "playTrainer", seat: "p1", uid });
67	}
68	
69	describe("M5 op-slice — discardEnergy", () => {
70	  it("registry resolves a program for each authored id (incl. the Giacomo reprints)", () => {
71	    for (const id of ["sv01-168", "sv02-182", "sv02-252", "sv02-267", "sv03-143"]) {
72	      expect(programFor(id)).toBeDefined();
73	    }
74	  });
75	
76	  // ── opponentChosen (Crushing Hammer / fix-hammer) ──
77	
78	  it("a single candidate is FORCED — it discards with no prompt at all", () => {
79	    let state = board(1);
80	    state = attachFromDeck(state, "p2", "fix-energy", 1);
81	    const energyUid = activeEnergy(state, "p2")[0] as string;
82	    const discardBefore = state.players.p2.discard.length;
83	
84	    const { state: done, events } = playFromHand(state, "fix-hammer");
85	
86	    expect(done.phase.kind).toBe("turn:action"); // never parked
87	    expect(activeEnergy(done, "p2")).toEqual([]);
88	    // The card goes to its OWNER's pile — the opponent's, not the controller's.
89	    expect(done.players.p2.discard).toContain(energyUid);
90	    expect(done.players.p2.discard.length).toBe(discardBefore + 1);
91	    expect(done.players.p1.discard).not.toContain(energyUid);
92	    // …and it lands on TOP of that pile (appended), the pile being ordered.
93	    expect(done.players.p2.discard.at(-1)).toBe(energyUid);
94	    const discarded = find(events, "ENERGY_DISCARDED");
95	    // `seat` is the VICTIM, `actor` the controller whose card did it — opposite
96	    // seats for a hammer, the SAME seat for the self-discard attack cost.
97	    expect(discarded).toMatchObject({ seat: "p2", actor: "p1", uids: [energyUid] });
98	    expect(discarded?.from).toEqual({ spot: "active" });
99	  });
100	
101	  it("two copies of ONE print on one Pokémon are interchangeable — forced, not parked", () => {
102	    // The M1 doctrine applied to card identity: either copy leaves the identical
103	    // board and the identical discard pile, so there is nothing to ask. Contrast
104	    // the two-DISTINCT-print cases below, which do park.
105	    let state = board(20);
106	    state = attachFromDeck(state, "p2", "fix-energy", 2);
107	    const before = activeEnergy(state, "p2");
108	
109	    const { state: done, events } = playFromHand(state, "fix-hammer");
110	
111	    expect(done.phase.kind).toBe("turn:action"); // never parked
112	    expect(types(events)).not.toContain("EFFECT_PENDING");
113	    // Exactly ONE came off — "one" is still one, collapsing does not discard more.
114	    expect(activeEnergy(done, "p2")).toEqual([before[1]]);
115	    expect(done.players.p2.discard).toContain(before[0]);
116	  });
117	
118	  it("identical prints on DIFFERENT Pokémon still park — the host is never fungible", () => {
119	    // The collapse keys on (host, card): which Pokémon loses the Energy is the
120	    // whole decision for a Crushing Hammer, so two identical Basic Energy on two
121	    // different bodies are two candidates, not one.
122	    let state = board(21);
123	    state = benchFromDeck(state, "p2", "fix-basic-2");
124	    state = attachFromDeck(state, "p2", "fix-energy", 1);
125	    state = attachBenchFromDeck(state, "p2", 0, "fix-energy", 1);
126	
127	    const { state: parked } = playFromHand(state, "fix-hammer");
128	    if (parked.phase.kind !== "effect:choose") throw new Error("expected effect:choose");
129	    if (parked.phase.prompt.kind !== "discardEnergy") throw new Error("expected discardEnergy");
130	    expect(parked.phase.prompt.discardable.map((d) => d.from)).toEqual([
131	      { seat: "p2", spot: { spot: "active" } },
132	      { seat: "p2", spot: { spot: "bench", index: 0 } },
133	    ]);
134	  });
135	
136	  it("parks on a real choice, offering EVERY Energy on the opponent's board (Active + Bench)", () => {
137	    let state = board(2);
138	    state = benchFromDeck(state, "p2", "fix-basic-2");
139	    state = attachFromDeck(state, "p2", "fix-energy", 1);
140	    state = attachBenchFromDeck(state, "p2", 0, "fix-special", 1);
141	    const onActive = activeEnergy(state, "p2")[0] as string;
142	    const onBench = benchEnergy(state, "p2", 0)[0] as string;
143	
144	    const { state: parked } = playFromHand(state, "fix-hammer");
145	
146	    expect(parked.phase.kind).toBe("effect:choose");
147	    if (parked.phase.kind !== "effect:choose") throw new Error("expected effect:choose");
148	    if (parked.phase.prompt.kind !== "discardEnergy") throw new Error("expected discardEnergy");
149	    const prompt = parked.phase.prompt;
150	    expect(prompt.scope).toEqual({ kind: "total", count: 1 });
151	    expect(prompt.note).toBe("Discard an Energy from 1 of your opponent's Pokémon.");
152	    // anyEnergy admits both the basic and the Special, each tagged with its host.
153	    expect(prompt.discardable.map((d) => d.uid)).toEqual([onActive, onBench]);
154	    expect(prompt.discardable[0]?.from).toEqual({ seat: "p2", spot: { spot: "active" } });
155	    expect(prompt.discardable[1]?.from).toEqual({ seat: "p2", spot: { spot: "bench", index: 0 } });
156	
157	    // Picking the BENCHED one takes it off the bench, leaving the Active untouched.
158	    const { state: done, events } = mustApply(parked, {
159	      type: "resolveEffect",
160	      seat: "p1",
161	      choice: { kind: "discardEnergy", uids: [onBench] },
162	    });
163	    expect(done.phase.kind).toBe("turn:action");
164	    expect(benchEnergy(done, "p2", 0)).toEqual([]);
165	    expect(activeEnergy(done, "p2")).toEqual([onActive]);
166	    expect(done.players.p2.discard).toContain(onBench);
167	    expect(find(events, "ENERGY_DISCARDED")?.from).toEqual({ spot: "bench", index: 0 });
168	
169	    // A SECOND hammer (Items are unbounded) now has one candidate left — forced —
170	    // and the pile stays a pile: the newer card goes ON TOP of the older one.
171	    const before = [...done.players.p2.discard];
172	    const { state: twice } = playFromHand(done, "fix-hammer");
173	    expect(twice.players.p2.discard).toEqual([...before, onActive]);
174	  });
175	
176	  it("offers the bench in INDEX order, and 'one' rejects a second Energy off a SECOND Pokémon", () => {
177	    // Two BENCHED holders and a bare Active — the board that tells the two bench
178	    // slots apart (a candidate list keyed only by "bench" would fuse them) and the
179	    // one where an over-long pick could otherwise slip past the per-Pokémon rule:
180	    // two uids off two DIFFERENT Pokémon break no "one Energy per Pokémon" check,
181	    // so only the exact count stops "1 of your opponent's Pokémon" taking two.
182	    let state = board(15);
183	    state = benchFromDeck(state, "p2", "fix-basic-2");
184	    state = benchFromDeck(state, "p2", "fix-basic-2");
185	    state = attachBenchFromDeck(state, "p2", 0, "fix-energy", 1);
186	    state = attachBenchFromDeck(state, "p2", 1, "fix-special", 1);
187	    const onBench0 = benchEnergy(state, "p2", 0)[0] as string;
188	    const onBench1 = benchEnergy(state, "p2", 1)[0] as string;
189	
190	    const { state: parked } = playFromHand(state, "fix-hammer");
191	    if (parked.phase.kind !== "effect:choose") throw new Error("expected effect:choose");
192	    if (parked.phase.prompt.kind !== "discardEnergy") throw new Error("expected discardEnergy");
193	    const prompt = parked.phase.prompt;
194	    // The Active holds nothing, so both candidates are benched — bench 0 first.
195	    expect(prompt.discardable.map((d) => d.uid)).toEqual([onBench0, onBench1]);
196	    expect(prompt.discardable.map((d) => d.from)).toEqual([
197	      { seat: "p2", spot: { spot: "bench", index: 0 } },
198	      { seat: "p2", spot: { spot: "bench", index: 1 } },
199	    ]);
200	
201	    expectErr(
202	      parked,
203	      {
204	        type: "resolveEffect",
205	        seat: "p1",
206	        choice: { kind: "discardEnergy", uids: [onBench0, onBench1] },
207	      },
208	      "BAD_EFFECT_CHOICE",
209	    );
210	    // The rejected wire answer changed nothing — both Energy are still attached.
211	    expect(benchEnergy(parked, "p2", 0)).toEqual([onBench0]);
212	    expect(benchEnergy(parked, "p2", 1)).toEqual([onBench1]);
213	  });
214	
215	  it("is NOT declinable — an empty pick is rejected, unlike a search or a move", () => {
216	    let state = board(3);
217	    // Two DISTINCT prints — two copies of one card are interchangeable and would
218	    // auto-resolve (forcedDiscards' fungibility collapse), never reaching a park.
219	    state = attachFromDeck(state, "p2", "fix-energy", 1);
220	    state = attachFromDeck(state, "p2", "fix-special", 1);
221	    const { state: parked } = playFromHand(state, "fix-hammer");
222	
223	    expectErr(
224	      parked,
225	      { type: "resolveEffect", seat: "p1", choice: { kind: "discardEnergy", uids: [] } },
226	      "BAD_EFFECT_CHOICE",
227	    );
228	    // …and two picks are equally wrong: "one" means exactly one.
229	    const both = activeEnergy(parked, "p2");
230	    expectErr(
231	      parked,
232	      { type: "resolveEffect", seat: "p1", choice: { kind: "discardEnergy", uids: both } },
233	      "BAD_EFFECT_CHOICE",
234	    );
235	  });
236	
237	  it("rejects an Energy that was never offered (a uid off the CONTROLLER's own board)", () => {
238	    let state = board(4);
239	    state = attachFromDeck(state, "p2", "fix-energy", 1); // two DISTINCT prints →
240	    state = attachFromDeck(state, "p2", "fix-special", 1); // a real choice → parks
241	    state = attachFromDeck(state, "p1", "fix-energy", 1); // the controller's own
242	    const mine = activeEnergy(state, "p1")[0] as string;
243	
244	    const { state: parked } = playFromHand(state, "fix-hammer");
245	    expectErr(
246	      parked,
247	      { type: "resolveEffect", seat: "p1", choice: { kind: "discardEnergy", uids: [mine] } },
248	      "BAD_EFFECT_CHOICE",
249	    );
250	  });
251	
252	  it("nothing on the opponent's board → the top-level play is rejected (whiff gate)", () => {
253	    const state = handFromDeck(board(5), "p1", "fix-hammer", 1);
254	    const uid = handUid(state, "p1", "fix-hammer");
255	    expectErr(state, { type: "playTrainer", seat: "p1", uid }, "NO_LEGAL_TARGET");
256	    // Rejected BEFORE the card leaves hand — the play costs nothing.
257	    expect(state.players.p1.hand).toContain(uid);
258	  });
259	
260	  it("Crushing Hammer into an Energy-less board is REJECTED — the flip is not an effect", () => {
261	    // §7 "you cannot play a card if it has no valid target" (Compendium 906,
262	    // reconfirmed 2025-06-26). A coin gate has no `otherwise`, so its heads branch
263	    // is the only thing the card can do; a branch that could only whiff makes the
264	    // whole card unplayable, and the flip — procedure, not effect — cannot rescue
265	    // it. `programPlayable` therefore DESCENDS into `coinFlipGate.then`.
266	    const bare = handFromDeck(board(6), "p1", "sv01-168", 1);
267	    const bareUid = handUid(bare, "p1", "sv01-168");
268	    expectErr(bare, { type: "playTrainer", seat: "p1", uid: bareUid }, "NO_LEGAL_TARGET");
269	    // Rejected before anything happens — the card stays in hand and NO coin was
270	    // flipped (a burnt flip would also advance the rng for both players).
271	    expect(bare.players.p1.hand).toContain(bareUid);
272	    expect(applyAction(bare, { type: "playTrainer", seat: "p1", uid: bareUid }).ok).toBe(false);
273	  });
274	
275	  it("Crushing Hammer: heads discards, tails does nothing", () => {
276	    // With exactly one Energy out there, a heads flip takes it and a tails does not
277	    // — seeds chosen so both faces are covered.
278	    const faces = new Map<string, { discarded: number; energyLeft: number }>();
279	    for (const seed of [1, 2, 3, 4, 5, 6, 7, 8]) {
280	      let state = board(seed);
