2556	  seed: number,
2557	  decks: { p1: string[]; p2: string[] } = { p1: MIXED_DECK, p2: MIXED_DECK },
2558	  opts: SetupOptions = {},
2559	): GameState {
2560	  let state = mustCreate(seed, decks).state;
2561	  if (state.phase.kind !== "setup:chooseFirst") throw new Error("expected setup:chooseFirst");
2562	  const winner = state.phase.coinWinner;
2563	  state = must(
2564	    applyAction(state, { type: "chooseFirstPlayer", seat: winner, first: opts.first ?? winner }),
2565	  );
2566	  // Both seats can be owed compensation (each off the other's mulligans), so
2567	  // every undecided seat has to answer before placement opens.
2568	  while (state.phase.kind === "setup:drawExtra") {
2569	    const phase = state.phase;
2570	    const seat = SEATS.find((s) => !phase.decided[s]);
2571	    if (seat === undefined) throw new Error("setup:drawExtra with every seat decided");
2572	    const count = opts.extraDraw?.[seat] ?? phase.owed[seat];
2573	    state = must(applyAction(state, { type: "setupDrawExtra", seat, count }));
2574	  }
2575	  for (const seat of SEATS) {
2576	    const activeId = opts.active?.[seat];
2577	    const uid =
2578	      activeId === undefined ? firstBasicInHand(state, seat) : handUid(state, seat, activeId);
2579	    state = must(applyAction(state, { type: "setupPlaceActive", seat, uid }));
2580	    for (const benchId of opts.bench?.[seat] ?? []) {
2581	      const benchUid = handUid(state, seat, benchId);
2582	      state = must(applyAction(state, { type: "setupPlaceBench", seat, uid: benchUid }));
2583	    }
2584	  }
2585	  for (const seat of SEATS) {
2586	    state = must(applyAction(state, { type: "setupReady", seat }));
2587	  }
2588	  return state;
