import { describe, expect, it } from "vitest";
import { applyAction, deriveAttackEffect, programFor } from "./index";
import type { GameEvent, GameState } from "./index";
import {
  HAIL_BLADE_DECK,
  attachBenchFromDeck,
  attachFromDeck,
  benchFromDeck,
  deepFreeze,
  driveSetup,
  mustApply,
  setActiveFromDeck,
  types,
} from "./testFixtures";

// P3-M5 — Chien-Pao ex "Hail Blade" (sv02-061), the FIRST registry-authored
// attack. Printed ({W}{W}, "60×"): "You may discard any amount of {W} Energy from
// your Pokémon. This attack does 60 damage for each card you discarded in this
// way." The registry program (registry.ts CHIEN_PAO) is two ops:
//   • discardEnergy from "yours" (the attacker's WHOLE own board), filter
//     providesEnergy {W}, count "any" → a DECLINABLE 0..all park whose count is
//     filed under the `discarded` §9.2 slot;
//   • damageDefender per 60, count "discarded" → 60 × that count to the DEFENDER
//     through snipeActive's full §8.5 W/R pipeline.
// The deriver deliberately REFUSES the variable-count sentence (effects.ts returns
// null), and attack.ts SUPPRESSES the printed "60×" base (the program owns the
// damage), so a 0-discard Hail Blade deals 0, not 60.

const HAIL_BLADE_TEXT =
  "You may discard any amount of {W} Energy from your Pokémon. This attack does 60 damage for each card you discarded in this way.";

function find<T extends GameEvent["type"]>(
  events: GameEvent[],
  type: T,
): Extract<GameEvent, { type: T }> | undefined {
  return events.find((e) => e.type === type) as Extract<GameEvent, { type: T }> | undefined;
}

function activeEnergy(state: GameState, seat: "p1" | "p2"): string[] {
  return [...(state.players[seat].active?.energy ?? [])];
}
function benchEnergy(state: GameState, seat: "p1" | "p2", index: number): string[] {
  return [...(state.players[seat].bench[index]?.energy ?? [])];
}

/** Setup with BOTH Actives pinned to the 300 HP fix-hail-wall, then open P1's
    turn 2 (P2 went first and passed) — P1's first unrestricted turn, so attacking
    is legal (§4). */
function board(seed: number): GameState {
  const state = driveSetup(
    seed,
    { p1: HAIL_BLADE_DECK, p2: HAIL_BLADE_DECK },
    { first: "p2", active: { p1: "fix-hail-wall", p2: "fix-hail-wall" } },
  );
  return mustApply(state, { type: "endTurn", seat: "p2" }).state;
}

/** P1 fields a Chien-Pao ex Active carrying `water` Basic {W} (its cost AND its
    discard fuel) + `filler` non-{W} Colorless Energy. `defender` optionally swaps
    P2's Active off the fix-hail-wall (the displaced wall becomes P2's Bench). */
function hailBlade(
  seed: number,
  opts: { water?: number; filler?: number; defender?: string } = {},
): GameState {
  let state = setActiveFromDeck(board(seed), "p1", "sv02-061");
  if (opts.defender !== undefined) state = setActiveFromDeck(state, "p2", opts.defender);
  if (opts.water) state = attachFromDeck(state, "p1", "fix-water-energy", opts.water);
  if (opts.filler) state = attachFromDeck(state, "p1", "fix-energy", opts.filler);
  return state;
}

describe("Chien-Pao ex 'Hail Blade' — the registry-authored variable-count discard → 60× snipe", () => {
  // ── (a) registry-authored, deriver refuses ──
  it("is REGISTRY-AUTHORED — every printed id has the attack program, but the deriver refuses the sentence", () => {
    for (const id of ["sv02-061", "sv02-236", "sv02-261", "sv02-274"]) {
      expect(programFor(id)?.attack).toBeDefined();
    }
    // effects.ts deliberately will not express a variable-count "any amount"
    // discard, so the deriver returns null and the registry program stands alone.
    expect(deriveAttackEffect(HAIL_BLADE_TEXT)).toBeNull();
  });

  // ── (b) the park: whole own board, {W}-only ──
  it("PARKS on a DECLINABLE upTo discard offering every {W} on the attacker's own board — never a non-{W}", () => {
    const state = hailBlade(1, { water: 2, filler: 1 });
    const energy = activeEnergy(state, "p1");
    const [w1, w2, colorless] = energy as [string, string, string];

    const { state: parked } = mustApply(state, { type: "attack", seat: "p1", index: 0 });
    if (parked.phase.kind !== "effect:choose") throw new Error("expected effect:choose");
    expect(parked.phase.seat).toBe("p1"); // the ATTACKER decides
    if (parked.phase.prompt.kind !== "discardEnergy") throw new Error("expected discardEnergy");
    const prompt = parked.phase.prompt;
    // 0..all (every offered Energy), the one declinable discard scope.
    expect(prompt.scope).toEqual({ kind: "upTo", max: 2 });
    // Only the two {W} are candidates — the Colorless attach is NOT offered.
    expect(prompt.discardable.map((d) => d.uid)).toEqual([w1, w2]);
    expect(prompt.discardable.map((d) => d.uid)).not.toContain(colorless);
    // …and they are the attacker's OWN Energy (from: "yours" scans P1's board).
    expect(prompt.discardable.every((d) => d.from.seat === "p1")).toBe(true);
    expect(prompt.discardable[0]?.from).toEqual({ seat: "p1", spot: { spot: "active" } });
  });

  // ── (c) discard k → 60×k, the events, no skip ──
  it("discards k Energy for 60×k damage — files ENERGY_DISCARDED {p1,p1}, no ATTACK_EFFECT_SKIPPED", () => {
    const state = hailBlade(5, { water: 3 });
    const w = activeEnergy(state, "p1"); // three {W}

    const { state: parked, events: atkEvents } = mustApply(state, {
      type: "attack",
      seat: "p1",
      index: 0,
    });
    // The program AUTHORS the damage, so the printed "60×" modifier and the effect
    // sentence are both simulated — nothing is flagged as skipped.
    expect(types(atkEvents)).not.toContain("ATTACK_EFFECT_SKIPPED");
    if (parked.phase.kind !== "effect:choose") throw new Error("expected effect:choose");
    if (parked.phase.prompt.kind !== "discardEnergy") throw new Error("expected discardEnergy");

    const { state: done, events } = mustApply(parked, {
      type: "resolveEffect",
      seat: "p1",
      choice: { kind: "discardEnergy", uids: w },
    });
    // The self-discard fires with the attacker as BOTH victim and actor.
    const discarded = find(events, "ENERGY_DISCARDED");
    expect(discarded).toMatchObject({ seat: "p1", actor: "p1" });
    expect(discarded?.uids).toEqual(w); // one event, all three off the Active
    expect(discarded?.from).toEqual({ spot: "active" });
    // The Energy landed in P1's OWN discard pile, off the board.
    expect(done.players.p1.discard).toEqual(expect.arrayContaining(w));
    expect(activeEnergy(done, "p1")).toEqual([]);
    // 60 × 3 = 180, flat (fix-hail-wall has no Weakness), no KO (300 HP).
    expect(find(events, "DAMAGE_DEALT")).toMatchObject({ base: 180, weakness: null, dealt: 180 });
    expect(done.players.p2.active?.damage).toBe(180);
    expect(types(events)).not.toContain("ATTACK_EFFECT_SKIPPED");
    expect(done.phase).toEqual({ kind: "turn:action", seat: "p2" });
  });

  // ── (d) decline → 0 damage (the "60× base suppressed" proof) ──
  it("DECLINING the discard (empty pick) deals 0 — the printed 60× base is suppressed", () => {
    const state = hailBlade(7, { water: 2 });
    const { state: parked } = mustApply(state, { type: "attack", seat: "p1", index: 0 });
    if (parked.phase.kind !== "effect:choose") throw new Error("expected effect:choose");
    if (parked.phase.prompt.kind !== "discardEnergy") throw new Error("expected discardEnergy");

    const { state: done, events } = mustApply(parked, {
      type: "resolveEffect",
      seat: "p1",
      choice: { kind: "discardEnergy", uids: [] },
    });
    // 0 discarded → count 0 → no damage placed AND no base leaking through.
    expect(types(events)).not.toContain("ENERGY_DISCARDED");
    expect(types(events)).not.toContain("DAMAGE_DEALT");
    expect(done.players.p2.active?.damage).toBe(0);
    // The Energy stayed attached (nothing was discarded), and the turn ended.
    expect(activeEnergy(done, "p1")).toHaveLength(2);
    expect(done.phase).toEqual({ kind: "turn:action", seat: "p2" });
  });

  // ── (e) whole-board reach: a benched {W} counts ──
  it("reaches the attacker's BENCH — a {W} on a benched Chien-Pao is offered and counts toward the damage", () => {
    let state = hailBlade(8, { water: 2 });
    state = benchFromDeck(state, "p1", "sv02-061"); // bench[1] (bench[0] is the displaced wall)
    state = attachBenchFromDeck(state, "p1", 1, "fix-water-energy", 1);
    const benchedWater = benchEnergy(state, "p1", 1)[0] as string;

    const { state: parked } = mustApply(state, { type: "attack", seat: "p1", index: 0 });
    if (parked.phase.kind !== "effect:choose") throw new Error("expected effect:choose");
    if (parked.phase.prompt.kind !== "discardEnergy") throw new Error("expected discardEnergy");
    const prompt = parked.phase.prompt;
    // The benched {W} is a candidate, tagged with its Bench host — from: "yours"
    // scans the WHOLE own board, not just the Active.
    expect(prompt.scope).toEqual({ kind: "upTo", max: 3 });
    expect(prompt.discardable.map((d) => d.uid)).toContain(benchedWater);
    const benchedRow = prompt.discardable.find((d) => d.uid === benchedWater);
    expect(benchedRow?.from).toEqual({ seat: "p1", spot: { spot: "bench", index: 1 } });

    // Discard ONLY the benched one → 60 × 1, taken off the Bench.
    const { state: done, events } = mustApply(parked, {
      type: "resolveEffect",
      seat: "p1",
      choice: { kind: "discardEnergy", uids: [benchedWater] },
    });
    const discarded = find(events, "ENERGY_DISCARDED");
    expect(discarded).toMatchObject({ seat: "p1", actor: "p1", uids: [benchedWater] });
    expect(discarded?.from).toEqual({ spot: "bench", index: 1 });
    expect(find(events, "DAMAGE_DEALT")).toMatchObject({ dealt: 60 });
    expect(done.players.p2.active?.damage).toBe(60);
    expect(benchEnergy(done, "p1", 1)).toEqual([]); // the benched {W} came off
    expect(activeEnergy(done, "p1")).toHaveLength(2); // the Active's cost {W} untouched
  });

  // ── (f) Weakness DOUBLES on the Active ──
  it("DOUBLES against a Water-weak defender — discard k gives 60×k×2 through the §8.5 pipeline", () => {
    const state = hailBlade(3, { water: 2, defender: "fix-water-weak" });
    const { state: parked } = mustApply(state, { type: "attack", seat: "p1", index: 0 });
    if (parked.phase.kind !== "effect:choose") throw new Error("expected effect:choose");
    if (parked.phase.prompt.kind !== "discardEnergy") throw new Error("expected discardEnergy");
    const w = parked.phase.prompt.discardable.map((d) => d.uid); // the two {W}

    const { state: done, events } = mustApply(parked, {
      type: "resolveEffect",
      seat: "p1",
      choice: { kind: "discardEnergy", uids: w },
    });
    // Chien-Pao ex is {W}; the defender is ×2 Water → (60 × 2) × 2 = 240.
    expect(find(events, "DAMAGE_DEALT")).toMatchObject({
      base: 120,
      weakness: { op: "multiply", amount: 2 },
      dealt: 240,
    });
    expect(done.players.p2.active?.damage).toBe(240); // 300 HP survives
  });

  // ── (g) a KO of an ex defender owes 2 Prizes (D93) ──
  it("KOs a rule-box ex defender and takes TWO Prizes through the epilogue sweep (D93)", () => {
    const state = hailBlade(9, { water: 2, defender: "fix-ko-ex" });
    const prizesBefore = state.players.p1.prizes.length;

    const { state: parked } = mustApply(state, { type: "attack", seat: "p1", index: 0 });
    if (parked.phase.kind !== "effect:choose") throw new Error("expected effect:choose");
    if (parked.phase.prompt.kind !== "discardEnergy") throw new Error("expected discardEnergy");
    const w = parked.phase.prompt.discardable.map((d) => d.uid); // two {W} → 120 damage

    const { state: after, events } = mustApply(parked, {
      type: "resolveEffect",
      seat: "p1",
      choice: { kind: "discardEnergy", uids: w },
    });
    // 60 × 2 = 120 ≥ 110 HP → KO, swept by the attack epilogue, owing 2 Prizes.
    expect(find(events, "KNOCKED_OUT")).toBeDefined();
    if (after.phase.kind !== "ko:takePrizes") throw new Error("expected ko:takePrizes");
    expect(after.phase.count).toBe(2);

    const { state: done } = mustApply(after, {
      type: "takePrizes",
      seat: "p1",
      prizeIndices: [0, 1],
    });
    expect(done.players.p1.prizes.length).toBe(prizesBefore - 2); // the rule box's real Prize count
    expect(done.phase).toEqual({ kind: "turn:action", seat: "p2" });
  });

  // ── purity ──
  it("never mutates the input state — the attack AND the resolve (frozen boards)", () => {
    const state = hailBlade(10, { water: 2 });
    expect(() =>
      applyAction(deepFreeze(state), { type: "attack", seat: "p1", index: 0 }),
    ).not.toThrow();

    const { state: parked } = mustApply(state, { type: "attack", seat: "p1", index: 0 });
    if (parked.phase.kind !== "effect:choose") throw new Error("expected effect:choose");
    if (parked.phase.prompt.kind !== "discardEnergy") throw new Error("expected discardEnergy");
    const w = parked.phase.prompt.discardable.map((d) => d.uid);
    expect(() =>
      applyAction(deepFreeze(parked), {
        type: "resolveEffect",
        seat: "p1",
        choice: { kind: "discardEnergy", uids: w },
      }),
    ).not.toThrow();
  });
});

