399	/** Does the record satisfy this gate? The base test is "did the earlier op file
400	    anything" — a whiffed op files an EMPTY array, which is why the length and not
401	    the key is what is asked.
402	
403	    `contains: "yourActive"` narrows it to "is any of those cards on the
404	    controller's Active" (Janine's Secret Art's "if you attached Energy to your
405	    **Active** Pokémon in this way"). Read off the live board rather than out of
406	    the record — see the op's doc for why the record's values stay one kind of
407	    thing, and for the three ops that would make this board reading differ from
408	    the historical one if a future card sequenced them in between — and against
409	    `state` AS OF the gate, with every earlier op applied. */
410	function recordGateHolds(
411	  state: GameState,
412	  ctx: EffectContext,
413	  op: Extract<EffectOp, { op: "recordGate" }>,
414	  record: EffectRecord,
415	): boolean {
416	  const filed = recorded(record, op.slot);
417	  if (filed.length === 0) return false;
418	  if (op.contains !== "yourActive") return true;
419	  const active = state.players[ctx.seat].active;
420	  if (active === null) return false;
421	  return filed.some((uid) => active.energy.includes(uid));
