322	export function runProgram(
323	  state: GameState,
324	  program: readonly EffectOp[],
325	  ctx: EffectContext,
326	  events: GameEvent[],
327	  /** What earlier ops recorded (§9.2). Every caller but `resumeProgram` starts a
328	      program from the top, where nothing has run yet — hence the default, which
329	      is also what keeps this widening invisible to attack.ts / cardplay.ts /
330	      triggers.ts / flow.ts. Mutated in place as the run proceeds, like `events`. */
331	  record: EffectRecord = {},
332	): RunResult {
333	  let next = state;
334	  const queue: EffectOp[] = [...program];
335	  while (queue.length > 0) {
336	    const op = queue.shift() as EffectOp;
337	    if (op.op === "coinFlipGate") {
338	      const [face, rngState] = flipCoin(next.rngState);
339	      next = { ...next, rngState };
340	      events.push({ type: "ATTACK_EFFECT_COIN_FLIP", seat: ctx.seat, result: face });
341	      if (face === "heads") queue.unshift(...op.then);
342	      continue;
343	    }
344	    if (op.op === "conditionGate") {
345	      // The deterministic gate (Falkner's Stadium, Grusha's "instead"), spliced
346	      // like the coin flip so an op inside a branch can still park. Evaluated
347	      // against `next` — the board AS OF this point, with every earlier op in
348	      // the program applied. No event: the condition is public (BoardCondition),
349	      // so unlike a coin flip it tells the opponent nothing they can't see.
350	      queue.unshift(...(conditionHolds(next, ctx.seat, op.cond) ? op.then : (op.otherwise ?? [])));
351	      continue;
352	    }
353	    if (op.op === "recordGate") {
354	      // The printed "in this way" / "if you do" (§9.2 — Miriam, Dendra), spliced
355	      // like the other two gates so an op inside a branch can still park. Reads
356	      // the RUNNING record, not `ctx`: what makes this gate different from the
357	      // other two is that its answer is produced by this very program, so it
358	      // must see writes made since the run started — including one made by an
359	      // op that parked and resolved through resolveEffect. No event: the
360	      // recording op already announced these cards by uid.
361	      queue.unshift(...(recordGateHolds(next, ctx, op, record) ? op.then : (op.otherwise ?? [])));
362	      continue;
363	    }
364	    const stepped = stepOp(next, op, ctx, events, record);
365	    if ("park" in stepped) {
366	      // rest = the queue as it stands after shifting `op` — a plain EffectOp[].
367	      return {
368	        kind: "parked",
369	        state: next,
370	        // The prompt describes its own op; a §9.2 gate makes the ANSWER buy
371	        // something the op cannot see. `queue` is the only place that is
372	        // knowable, which is why this is folded in here and not in the note.
373	        prompt: withConsequence(stepped.park, op, queue),
374	        cont: { pendingOp: op, rest: [...queue], ctx, ...carriedRecord(record) },
375	        ...(stepped.decider === undefined ? {} : { decider: stepped.decider }),
376	      };
377	    }
378	    next = stepped.done;
379	  }
380	  return { kind: "done", state: next };
381	}

